using System.Collections;
using LittleLeo.Variables;
using UnityEngine;

namespace Astrea;

public class SothisTutorialHandler : HighlightHandler
{
	[SerializeField]
	private ZoomableInstanceReference soulHeatZoomableInstanceReference;

	private bool enableInput;

	private bool turnOffTutorialInputReceived;

	private void Start()
	{
		highlightSpriteRenderer.SetRendererFloat(mpb, "_Threshold", 8f);
	}

	public void PlayHighlightAnimationAndShowTooltip()
	{
		HighLightAnimation("_Threshold", 0.02f, delegate
		{
			soulHeatZoomableInstanceReference.Value.OnMouseOver();
			StartCoroutine(TooltipShowedStartDelayToInput());
		});
	}

	private IEnumerator TooltipShowedStartDelayToInput()
	{
		yield return new WaitForSeconds(0.5f);
		enableInput = true;
	}

	private void Update()
	{
		if (!ReferenceSingleton<InputManager>.Instance.IsPaused && enableInput && ReferenceSingleton<InputManager>.Instance.IsJoystickBeingUsed && ReferenceSingleton<InputManager>.Instance.GetSelectButtonUp())
		{
			TurnOffHighlightAndTooltipAndInitializeBattle();
		}
	}

	public void OnMouseClicked()
	{
		if (!ReferenceSingleton<InputManager>.Instance.IsJoystickBeingUsed && !ReferenceSingleton<InputManager>.Instance.IsPaused && enableInput)
		{
			TurnOffHighlightAndTooltipAndInitializeBattle();
		}
	}

	private void TurnOffHighlightAndTooltipAndInitializeBattle()
	{
		turnOffTutorialInputReceived = true;
		soulHeatZoomableInstanceReference.Value.OnMouseExit();
		HighLightAnimation("_Threshold", 8f, delegate
		{
			ReferenceSingleton<GameStateManager>.Instance.SetState(ReferenceSingleton<GameStateManager>.Instance.InitializeBattleState);
			Object.Destroy(base.gameObject);
		});
	}

	public void OnOptionsButtonPressedAlternative()
	{
		if (!turnOffTutorialInputReceived)
		{
			soulHeatZoomableInstanceReference.Value.OnMouseExit();
		}
	}

	public void OnResumeButtonPressed()
	{
		if (!turnOffTutorialInputReceived)
		{
			soulHeatZoomableInstanceReference.Value.OnMouseOver();
		}
	}
}
